import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2022_waste.csv')
adj_df = pd.read_csv(ADJACENCY_PATH)

# Prepare adjacency dictionary
adjacency = {}
for borough in df['borough']:
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    adjacency[borough] = neighbors

# Initialize variables
waste_values = df.set_index('borough')['Waste_value'].to_dict()
boroughs = list(waste_values.keys())
n = len(boroughs)

# Iterative R method implementation
def iterative_r_method(waste_values, adjacency, max_iter=10, tol=1e-6):
    # Initial local means (naive)
    local_means = {}
    for borough in waste_values:
        neighbors = adjacency.get(borough, [])
        neighbor_values = [waste_values[n] for n in neighbors if n in waste_values]
        local_means[borough] = np.mean(neighbor_values) if neighbor_values else np.nan

    # Global regression (borough value ~ local mean)
    valid = ~pd.Series(local_means).isna()
    X = np.array([local_means[b] for b in boroughs if valid[b]])
    y = np.array([waste_values[b] for b in boroughs if valid[b]])
    if len(X) > 0:
        beta = np.linalg.lstsq(X.reshape(-1, 1), y, rcond=None)[0][0]
    else:
        beta = 1

    # Iteratively adjust
    for _ in range(max_iter):
        residuals = {}
        for borough in waste_values:
            if borough in local_means and not np.isnan(local_means[borough]):
                predicted = beta * local_means[borough]
                residuals[borough] = waste_values[borough] - predicted
            else:
                residuals[borough] = np.nan

        # Update local means excluding potential outliers
        new_local_means = {}
        for borough in waste_values:
            neighbors = adjacency.get(borough, [])
            neighbor_residuals = [residuals[n] for n in neighbors if n in residuals and not np.isnan(residuals[n])]
            if neighbor_residuals:
                median_residual = np.median(neighbor_residuals)
                mad = np.median(np.abs(neighbor_residuals - median_residual))
                # Exclude neighbors with large residuals
                filtered_neighbors = [
                    n for n in neighbors 
                    if n in residuals and not np.isnan(residuals[n]) 
                    and np.abs(residuals[n] - median_residual) <= 3 * mad
                ]
                neighbor_values = [waste_values[n] for n in filtered_neighbors if n in waste_values]
                new_local_means[borough] = np.mean(neighbor_values) if neighbor_values else local_means.get(borough, np.nan)
            else:
                new_local_means[borough] = local_means.get(borough, np.nan)

        # Check convergence
        if all(np.isclose(new_local_means.get(b, 0), local_means.get(b, 0), atol=tol, equal_nan=True) for b in waste_values):
            break
        local_means = new_local_means

        # Re-estimate beta
        valid = ~pd.Series(local_means).isna()
        X = np.array([local_means[b] for b in boroughs if valid[b]])
        y = np.array([waste_values[b] for b in boroughs if valid[b]])
        if len(X) > 0:
            beta = np.linalg.lstsq(X.reshape(-1, 1), y, rcond=None)[0][0]

    # Final residuals and z-scores
    final_residuals = {}
    for borough in waste_values:
        if borough in local_means and not np.isnan(local_means[borough]):
            predicted = beta * local_means[borough]
            final_residuals[borough] = waste_values[borough] - predicted
        else:
            final_residuals[borough] = np.nan

    residual_values = np.array([final_residuals[b] for b in boroughs if not np.isnan(final_residuals[b])])
    if len(residual_values) > 0:
        median_residual = np.median(residual_values)
        mad = np.median(np.abs(residual_values - median_residual))
        z_scores = {b: (final_residuals[b] - median_residual) / (1.4826 * mad) if not np.isnan(final_residuals[b]) else np.nan for b in boroughs}
    else:
        z_scores = {b: np.nan for b in boroughs}

    return z_scores

# Run analysis
z_scores = iterative_r_method(waste_values, adjacency)

# Get Tower Hamlets result
tower_hamlets_z = z_scores.get('Tower Hamlets', np.nan)

# Determine outlier status
if not np.isnan(tower_hamlets_z):
    if tower_hamlets_z > 2.5:
        result = f"FINAL ANSWER: OUTLIER - HIGH (z = {tower_hamlets_z})"
    elif tower_hamlets_z < -2.5:
        result = f"FINAL ANSWER: OUTLIER - LOW (z = {tower_hamlets_z})"
    else:
        result = f"FINAL ANSWER: NOT AN OUTLIER (z = {tower_hamlets_z})"
else:
    result = "FINAL ANSWER: NOT AN OUTLIER (z = nan)"

print(result)
